/**
 * tools/art/induct_all_ground_tiles.js
 *
 * Inducts all PixelLab ground tiles generated by the Owner into Project DEUS:
 * 1. Reads the Owner's PixelLab Tiles Pro backup directory:
 *    C:/Users/snewt/DEUS_backups/pixellab_2026-09-30/tiles_pro
 * 2. Snaps all tile colors to the DEUS master world palette (art/palette/deus_master_world_palette_v1.hex)
 * 3. Builds 96x144 RMMZ A2 autotile blocks for all surface and underground terrains
 * 4. Writes game/img/tilesets/Outside_A2.png (768x576) with all 32 autotile slots populated
 * 5. Writes game/img/tilesets/Dungeon_A2.png (768x576) with all underground autotile slots populated
 * 6. Writes game/img/tilesets/DEUS_GroundVar_D.png (768x768) with individual 48x48 swatches of all 55 sets
 * 7. Saves all master source sets to art/masters/source_sets/ with metadata sidecars
 */

