// 5. Load and palette-snap a specimen 48x48 tile
function loadAndSnapTile(spec) {
    let rawBuf;
    if (spec.sourceType === 'owner_master') {
        const img = decodePNG(fs.readFileSync(spec.sourcePath));
        rawBuf = img.data;
    } else {
        const pad = spec.fillTile < 10 ? '0' + spec.fillTile : '' + spec.fillTile;
        const imgPath = path.join(BACKUP_DIR, `${spec.pixellabId}__${pad}.png`);
        if (!fs.existsSync(imgPath)) throw new Error(`Missing tile image: ${imgPath}`);
        const img = decodePNG(fs.readFileSync(imgPath));
        rawBuf = img.data;
    }

    const seamless = makeSeamless(rawBuf, 48, 48, 4);
    const snapped = Buffer.alloc(48 * 48 * 4);

    for (let i = 0; i < 48 * 48 * 4; i += 4) {
        const s = snap(seamless[i], seamless[i + 1], seamless[i + 2]);
        snapped[i] = s[0];
        snapped[i + 1] = s[1];
        snapped[i + 2] = s[2];
        snapped[i + 3] = 255; // Binary alpha: opaque ground
    }
    return snapped;
}

// 6. Induct and assemble tilesets
console.log('--- Inducting All Ground Tiles ---');

// Process all specimens and build A2 autotile blocks
const processedTiles = {};
const a2Blocks = {};

for (const [key, spec] of Object.entries(SPECIMENS)) {
    console.log(`Processing: ${spec.name} (${spec.canonicalId})...`);
    const tileBuf = loadAndSnapTile(spec);
    processedTiles[key] = tileBuf;

    // Save master tile to art/masters/source_sets
    const setDir = path.join(ROOT, 'art', 'masters', 'source_sets', spec.canonicalId);
    fs.mkdirSync(setDir, { recursive: true });
    writePNG(path.join(setDir, 'variant_0.png'), 48, 48, tileBuf);

    // Write sidecar metadata
    const meta = {
        canonicalId: spec.canonicalId,
        name: spec.name,
        date: '2026-09-30',
        author: 'Owner (PixelLab)',
        pixellabId: spec.pixellabId || 'owner_anchor',
        fillTile: spec.fillTile !== undefined ? spec.fillTile : 0,
        palette: 'deus_master_world_palette_v1.hex',
        dimensions: { width: 48, height: 48 }
    };
    fs.writeFileSync(path.join(setDir, 'manifest.json'), JSON.stringify(meta, null, 2), 'utf8');

    // Build 96x144 autotile block
    const block = buildA2Block(tileBuf, spec.edge, spec.hi);
    a2Blocks[key] = block;
}

// 7. Write Outside_A2.png (768x576)
console.log('Assembling Outside_A2.png...');
const outsideA2Buf = Buffer.alloc(768 * 576 * 4, 0);

// Helper to blit a 96x144 block into Outside_A2 slot (0..31)
// Slots: 8 columns x 4 rows
function blitA2Block(targetBuf, sheetWidth, slotIdx, blockBuf) {
    const col = slotIdx % 8;
    const row = Math.floor(slotIdx / 8);
    const startX = col * 96;
    const startY = row * 144;

    for (let y = 0; y < 144; y++) {
        for (let x = 0; x < 96; x++) {
            const si = (y * 96 + x) * 4;
            const di = ((startY + y) * sheetWidth + (startX + x)) * 4;
            targetBuf[di]     = blockBuf[si];
            targetBuf[di + 1] = blockBuf[si + 1];
            targetBuf[di + 2] = blockBuf[si + 2];
            targetBuf[di + 3] = blockBuf[si + 3];
        }
    }
}

